#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> days(n);
    for (int i = 0; i < n; i++) cin >> days[i];
    long long c1;
    long long c7;
    long long c30;
    cin >> c1 >> c7 >> c30;

    int last = (int)days[n - 1];
    vector<char> travel(last + 1, 0);
    for (long long d : days) travel[d] = 1;
    vector<long long> cost(last + 1, 0);
    for (int d = 1; d <= last; d++) {
        if (!travel[d]) {
            cost[d] = cost[d - 1];
        } else {
            long long a = cost[d - 1] + c1;
            long long b = cost[d > 7 ? d - 7 : 0] + c7;
            long long c = cost[d > 30 ? d - 30 : 0] + c30;
            cost[d] = min(a, min(b, c));
        }
    }
    cout << cost[last] << "\n";

    return 0;
}

