import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] days = new long[(int) n];
        for (int i = 0; i < days.length; i++) days[i] = Long.parseLong(next());
        long c1 = Long.parseLong(next());
        long c7 = Long.parseLong(next());
        long c30 = Long.parseLong(next());

        int last = (int) days[(int) n - 1];
        boolean[] travel = new boolean[last + 1];
        for (int i = 0; i < n; i++) travel[(int) days[i]] = true;
        long[] cost = new long[last + 1];
        for (int d = 1; d <= last; d++) {
            if (!travel[d]) {
                cost[d] = cost[d - 1];
            } else {
                long a = cost[d - 1] + c1;
                long b = cost[d > 7 ? d - 7 : 0] + c7;
                long c = cost[d > 30 ? d - 30 : 0] + c30;
                cost[d] = Math.min(a, Math.min(b, c));
            }
        }
        System.out.println(cost[last]);
    }
}
